CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001003421_InicialCreacion') THEN
    CREATE TABLE categorias (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(80) NOT NULL,
        CONSTRAINT "PK_categorias" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001003421_InicialCreacion') THEN
    CREATE TABLE clientes (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(120) NOT NULL,
        "Telefono" character varying(20),
        "LimiteCredito" numeric(12,2) NOT NULL,
        "SaldoActual" numeric(12,2) NOT NULL,
        "Activo" boolean NOT NULL,
        CONSTRAINT "PK_clientes" PRIMARY KEY ("Id"),
        CONSTRAINT ck_clientes_saldo CHECK ("SaldoActual" >= 0 AND "SaldoActual" <= "LimiteCredito")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001003421_InicialCreacion') THEN
    CREATE TABLE roles (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(50) NOT NULL,
        CONSTRAINT "PK_roles" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001003421_InicialCreacion') THEN
    CREATE TABLE productos (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CodigoBarras" character varying(50),
        "Nombre" character varying(150) NOT NULL,
        "PrecioCompra" numeric(12,2) NOT NULL,
        "PrecioVenta" numeric(12,2) NOT NULL,
        "StockActual" integer NOT NULL,
        "StockMinimo" integer NOT NULL,
        "Activo" boolean NOT NULL,
        "CategoriaId" integer NOT NULL,
        CONSTRAINT "PK_productos" PRIMARY KEY ("Id"),
        CONSTRAINT ck_productos_precio_venta CHECK ("PrecioVenta" >= "PrecioCompra"),
        CONSTRAINT ck_productos_stock CHECK ("StockActual" >= 0 AND "StockMinimo" >= 0),
        CONSTRAINT "FK_productos_categorias_CategoriaId" FOREIGN KEY ("CategoriaId") REFERENCES categorias ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001003421_InicialCreacion') THEN
    CREATE TABLE usuarios (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(120) NOT NULL,
        "Username" character varying(50) NOT NULL,
        "PasswordHash" character varying(100) NOT NULL,
        "Activo" boolean NOT NULL,
        "RolId" integer NOT NULL,
        CONSTRAINT "PK_usuarios" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_usuarios_roles_RolId" FOREIGN KEY ("RolId") REFERENCES roles ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001003421_InicialCreacion') THEN
    CREATE TABLE movimientos_inventario (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Fecha" timestamp with time zone NOT NULL,
        "Tipo" character varying(20) NOT NULL,
        "Cantidad" integer NOT NULL,
        "CostoUnitario" numeric(12,2),
        "Motivo" character varying(250),
        "ProductoId" integer NOT NULL,
        "UsuarioId" integer NOT NULL,
        CONSTRAINT "PK_movimientos_inventario" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_movimientos_inventario_productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES productos ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_movimientos_inventario_usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES usuarios ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001003421_InicialCreacion') THEN
    CREATE TABLE turnos_caja (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "FechaApertura" timestamp with time zone NOT NULL,
        "MontoInicial" numeric(12,2) NOT NULL,
        "FechaCierre" timestamp with time zone,
        "MontoEsperado" numeric(12,2),
        "MontoContado" numeric(12,2),
        "Diferencia" numeric(12,2),
        "UsuarioId" integer NOT NULL,
        CONSTRAINT "PK_turnos_caja" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_turnos_caja_usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES usuarios ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001003421_InicialCreacion') THEN
    CREATE TABLE movimientos_caja (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Fecha" timestamp with time zone NOT NULL,
        "Tipo" character varying(20) NOT NULL,
        "Monto" numeric(12,2) NOT NULL,
        "Descripcion" character varying(250) NOT NULL,
        "TurnoCajaId" integer NOT NULL,
        "UsuarioId" integer NOT NULL,
        "ClienteId" integer,
        CONSTRAINT "PK_movimientos_caja" PRIMARY KEY ("Id"),
        CONSTRAINT ck_movimientos_caja_monto CHECK ("Monto" >= 0),
        CONSTRAINT "FK_movimientos_caja_clientes_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES clientes ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_movimientos_caja_turnos_caja_TurnoCajaId" FOREIGN KEY ("TurnoCajaId") REFERENCES turnos_caja ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_movimientos_caja_usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES usuarios ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
