        "ProductoId" integer NOT NULL,
        CONSTRAINT "PK_detalle_ventas" PRIMARY KEY ("Id"),
        CONSTRAINT ck_detalle_ventas_cantidad CHECK ("Cantidad" > 0),
        CONSTRAINT "FK_detalle_ventas_productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES productos ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_detalle_ventas_ventas_VentaId" FOREIGN KEY ("VentaId") REFERENCES ventas ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

