DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001003421_InicialCreacion') THEN
    PERFORM setval(
        pg_get_serial_sequence('categorias', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM categorias) + 1,
            nextval(pg_get_serial_sequence('categorias', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('roles', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM roles) + 1,
            nextval(pg_get_serial_sequence('roles', 'Id'))),
        false);
    END IF;
END $EF$;

