DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001010932_AgregarAlertasWhatsApp') THEN
    CREATE TABLE alertas (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Tipo" character varying(40) NOT NULL,
        "Severidad" character varying(20) NOT NULL,
        "Clave" character varying(100) NOT NULL,
        "Titulo" character varying(150) NOT NULL,
        "Mensaje" character varying(2000) NOT NULL,
        "Fecha" timestamp with time zone NOT NULL,
        "Leida" boolean NOT NULL,
        "FechaLeida" timestamp with time zone,
        "Activa" boolean NOT NULL,
        "FechaResolucion" timestamp with time zone,
        CONSTRAINT "PK_alertas" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261001010932_AgregarAlertasWhatsApp') THEN
    CREATE TABLE destinatarios_alerta (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(120) NOT NULL,
        "Telefono" character varying(20) NOT NULL,
        "ApiKey" character varying(100),
        "Activo" boolean NOT NULL,
        CONSTRAINT "PK_destinatarios_alerta" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
