    CREATE TABLE notificaciones_whatsapp (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Mensaje" character varying(2000) NOT NULL,
        "Estado" character varying(20) NOT NULL,
        "Intentos" integer NOT NULL,
        "UltimoError" character varying(500),
        "FechaCreacion" timestamp with time zone NOT NULL,
        "ProximoIntento" timestamp with time zone NOT NULL,
        "FechaEnvio" timestamp with time zone,
        "AlertaId" integer,
        "DestinatarioId" integer NOT NULL,
        CONSTRAINT "PK_notificaciones_whatsapp" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_notificaciones_whatsapp_alertas_AlertaId" FOREIGN KEY ("AlertaId") REFERENCES alertas ("Id") ON DELETE SET NULL,
        CONSTRAINT "FK_notificaciones_whatsapp_destinatarios_alerta_DestinatarioId" FOREIGN KEY ("DestinatarioId") REFERENCES destinatarios_alerta ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

